(6541410, 972442, 89723, '<td valign="top">Very nice job! Took me a bit. 9 Just went through all the other shots and it looks like this one will ribbon.</td>', 'Very nice job! Took me a bit. 9 Just went through all the other shots and it looks like this one will ribbon.', '2011-09-15 23:28:33.000000', NULL, 1),
(6541454, 973171, 30982, '<td valign="top">Sorry, Lev, still can''t find Waldo.  More importantly, I can''t believe you found a Hauptbahnhof this empty!!  (No vote.)</td>', 'Sorry, Lev, still can''t find Waldo.  More importantly, I can''t believe you found a Hauptbahnhof this empty!!  (No vote.)', '2011-09-16 00:16:23.000000', NULL, 1),
